mapper.sql:
WHERE 1 = 1
AND ( r.reservation_number LIKE CONCAT( '%', #{condition.keyword}, '%' )
OR m.email LIKE CONCAT( '%', #{condition.keyword}, '%' )
OR m.name LIKE CONCAT( '%', #{condition.keyword}, '%' )
OR c.title LIKE CONCAT( '%', #{condition.keyword}, '%' ) )
AND r.status = #{condition.status}
AND r.performance_id = #{condition.performanceId}
AND r.created_at >= #{condition.from}
AND r.created_at <= #{condition.to}
